import { readFileSync } from "fs";

const [s, t] = readFileSync(0, "utf8").trim().split("\n");
const n = s.length;
const m = t.length;

// dp[i][j] = S の先頭 i 文字を T の先頭 j 文字にする最小回数。2 行だけ持つ
let prev = new Int32Array(m + 1);
let cur = new Int32Array(m + 1);
for (let j = 0; j <= m; j++) prev[j] = j; // 空文字列から j 文字を挿入
for (let i = 1; i <= n; i++) {
  cur[0] = i; // i 文字を削除して空文字列に
  for (let j = 1; j <= m; j++) {
    const replace = prev[j - 1] + (s[i - 1] === t[j - 1] ? 0 : 1);
    cur[j] = Math.min(replace, prev[j] + 1, cur[j - 1] + 1);
  }
  [prev, cur] = [cur, prev];
}
